!function(r){function i(i){for(var e,p,o=i[0],u=i[1],m=i[2],s=0,g=[];s<o.length;s++)p=o[s],Object.prototype.hasOwnProperty.call(a,p)&&a[p]&&g.push(a[p][0]),a[p]=0;for(e in u)Object.prototype.hasOwnProperty.call(u,e)&&(r[e]=u[e]);for(c&&c(i);g.length;)g.shift()();return n.push.apply(n,m||[]),t()}function t(){for(var r,i=0;i<n.length;i++){for(var t,p=n[i],o=!0,u=1;u<p.length;u++)t=p[u],0!==a[t]&&(o=!1);o&&(n.splice(i--,1),r=e(e.s=p[0]))}return r}function e(i){if(p[i])return p[i].exports;var t=p[i]={i:i,l:!1,exports:{}};return r[i].call(t.exports,t,t.exports,e),t.l=!0,t.exports}var p={},a={12:0},n=[];e.m=r,e.c=p,e.d=function(r,i,t){e.o(r,i)||Object.defineProperty(r,i,{enumerable:!0,get:t})},e.r=function(r){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(r,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(r,"__esModule",{value:!0})},e.t=function(r,i){if(1&i&&(r=e(r)),8&i)return r;if(4&i&&"object"==typeof r&&r&&r.__esModule)return r;var t=Object.create(null);if(e.r(t),Object.defineProperty(t,"default",{enumerable:!0,value:r}),2&i&&"string"!=typeof r)for(var p in r)e.d(t,p,function(i){return r[i]}.bind(null,p));return t},e.n=function(r){var i=r&&r.__esModule?function(){return r.default}:function(){return r};return e.d(i,"a",i),i},e.o=function(r,i){return Object.prototype.hasOwnProperty.call(r,i)},e.p="";var o=window.webpackJsonp=window.webpackJsonp||[],u=o.push.bind(o);o.push=i,o=o.slice();for(var m=0;m<o.length;m++)i(o[m]);var c=u;n.push([78,0]),t()}({78:function(r,i,t){"use strict";t.r(i);var e=t(0);Object(e.a)("ru","army",t(79),t(1))},79:function(r){r.exports=JSON.parse('{"category":[{"name":"苏联","link":"ru_shortcut"},{"name":"陆战武器","link":"ru_army"},{"name":"轻武器","link":"ru_army#ru_army_iw"}],"model":"DP型轻机枪","description":"<h6>综述：</h6><p>二战期间，苏军使用的轻机枪主要是DP型轻机枪，该枪由于使用转盘式供弹，故又称为转盘式轻机枪。DP型轻机枪由苏联人瓦西里·捷格加廖夫于1927年研制成功，1928年开始装备苏联红军，该型枪还有多种改型，如DT型坦克机枪、DA型航空机枪及DA-2型双管航空机枪等，1944年又开发出改进型DPM型轻机枪。DP系列轻机枪产量很大，从1928年至1950年停止生产，一共生产了795000挺。</p><p>在二战苏联卫国战争整个过程中，都可见到DP型轻机枪的战斗身影，它是苏军步兵班排的必配武器，虽然它算不上是同时期最好的轻机枪，如连续射击时会因枪管过热而无法工作，且因整枪前重后轻而不适合携带中射击，但它在苏军的各场战斗中都发挥了不少作用，很受苏军步兵的喜爱。</p>","part1title":"系列型号","part1description":"","part1content":[{"image":"imgs/ru/army/ru_army_iwDP_10.jpg","description":"<h6>DP型轻机枪</h6><p></p><p>基本技术数据：</p><p>枪口径：7.62毫米；</p><p>枪全长：1270毫米；枪管长：605毫米；</p><p>枪重量：9.12公斤；</p><p>最大射速：600发/分钟；</p><p>有效射程：800米；</p><p>供弹方式：盘型弹匣，弹容量：47发。</p>","caption":""},{"image":"imgs/ru/army/ru_army_iwDP_11.jpg","description":"<p>DT型坦克轻机枪是DP系列轻机枪中的一种，性能与DP基本相同，但弹盘容量增加为60发，分步兵使用和坦克使用两种。</p><p>图中1为步兵用DT轻机枪；图中2为坦克用DT轻机枪。</p>","caption":""}],"part2title":"战场上的DP型轻机枪","part2description":"","part2content":[{"image":"imgs/ru/army/ru_army_iwDP_20.jpg","description":"（图左）1941年，一名隶属苏军第201空降旅的DP轻机枪手（该旅曾被用作步兵作战）。（图中）1943年，一名手持DP轻机枪的苏军第72预备役团列兵。（图右）1942年，一名苏军214空降团的DP轻机枪手。","caption":""},{"image":"imgs/ru/army/ru_army_iwDP_21.jpg","description":"1941年，东线苏联战场，坚守在斯摩棱斯克的苏军一个轻机枪组，其在楼房中持DP轻机枪向进攻的德军射击。","caption":""},{"image":"imgs/ru/army/ru_army_iwDP_22.jpg","description":"1942年，东线苏联战场，斯大林格勒保卫战中，一个苏军战斗小组坚守在城中的废墟里，几名战士正抓紧时间进食，一名士兵正手持DP轻机枪为他们警戒。","caption":""},{"image":"imgs/ru/army/ru_army_iwDP_23.jpg","description":"1942年，东线苏联战场，斯大林格勒保卫战中，一个持DP轻机枪与德军作战的苏军轻机枪组，由于该枪有较大射速，且有较大范围的火力覆盖面积，因此对德军的杀伤力相当大。","caption":""},{"image":"imgs/ru/army/ru_army_iwDP_24.jpg","description":"二战东线苏联战场，苏军一挺DP轻机枪为发起冲锋的士兵作火力支援。","caption":""},{"image":"imgs/ru/army/ru_army_iwDP_25.jpg","description":"二战东线苏联战场，战壕中的苏军士兵正利用战争间隙休息，但一名苏军机枪手仍然怀抱一挺DP轻机枪警惕地注视着战壕外的状况。","caption":""},{"image":"imgs/ru/army/ru_army_iwDP_26.jpg","description":"1941年夏天，东线苏联战场，隐蔽在掩体阵地中的苏军一挺DP轻机枪与机枪手。","caption":""},{"image":"imgs/ru/army/ru_army_iwDP_27.jpg","description":"二战东线苏联战场，草丛中，一位苏军女战士正在救助一名伤兵，一挺DP轻机枪正在一旁为他们作掩护。","caption":""},{"image":"imgs/ru/army/ru_army_iwDP_28.jpg","description":"二战东线苏联战场，一支正在向前线进发的苏军部队，队伍中一名机枪手正扛着一挺DP轻机枪。作为一种班组火力支援武器，DP轻机枪在一线连排中都会配备。","caption":""},{"image":"imgs/ru/army/ru_army_iwDP_29.jpg","description":"1944年8月，东线战场，苏军正向立陶宛西北部马里安波尔地区挺进，一挺DP轻机枪正在为进攻的苏军士兵作掩护。","caption":""},{"image":"imgs/ru/army/ru_army_iwDP_30.jpg","description":"二战东线苏联战场，一名苏军机枪手在一辆被击毁的德军突击炮车旁，将一挺DP轻机枪架在炮车上对低空俯冲的德军轰炸机射击。","caption":""},{"image":"imgs/ru/army/ru_army_iwDP_31.jpg","description":"二战东线苏联敌后战场，一名扛着DP轻机枪的苏联敌后游击队机枪手，他的脸上充满了自信的微笑。","caption":""},{"image":"imgs/ru/army/ru_army_iwDP_32.jpg","description":"二战东线苏联战场，隐蔽在一处精心构筑的防御工事中的苏军轻机枪班组，他们装备的是由DP轻机枪改造的DT轻机枪，它的枪管更重，弹盘容量60发（图中可看出该机枪弹盘与容量为47发的DP型机枪弹盘有所不同），持续射击时间更长，这种轻机枪主要是配备给坦克使用，故也称为坦克机枪，但在苏联卫国战争初期，DT坦克机枪也给不少苏军步兵配发使用。","caption":""},{"image":"imgs/ru/army/ru_army_iwDP_33.jpg","description":"1945年，东线德国战场，战斗中的一个苏军机枪小组，其使用的的是一挺DT坦克轻机枪。在这场激烈的战斗中，机枪手已经负伤，但仍坚持战斗。","caption":""},{"image":"imgs/ru/army/ru_army_iwDP_34.jpg","description":"绘画：1945年，在德国柏林的城市巷战中，一名手持DP轻机枪的苏军机枪手被躲在楼房内的德军击中的情景。DP轻机枪对德军杀伤力极大，因此其机枪手常常会被德军重点“照顾”，故死伤率也较其它步兵为多。","caption":""},{"image":"imgs/ru/army/ru_army_iwDP_35.jpg","description":"绘画：二战期间，一个正在进行作战演练的苏军DP轻机枪小组。","caption":""}]}')}});